@router.get("/videos/{video_id}/media")
@router.head("/videos/{video_id}/media")
@router.get("/videos/{video_id}/thumbnail")
@router.head("/videos/{video_id}/thumbnail")
def media(video_id: UUID, request: Request, user: Viewer, videos: Service):
    asset = videos.watch(
        user, video_id, "playback" if request.url.path.endswith("/media") else "thumbnail"
    )
    size = asset["size_bytes"]
    selected = byte_range(request.headers.get("range"), size) if request.method == "GET" else None
    headers = {
        "Accept-Ranges": "bytes",
        "Content-Length": str(size),
        "Content-Type": asset["content_type"],
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
    }
    storage = request.app.state.storage
    try:
        if storage.head(asset["object_key"])["ContentLength"] != size:
            raise RuntimeError("Asset size mismatch")
        if request.method == "HEAD":
            return Response(headers=headers)
        args = {"Range": f"bytes={selected[0]}-{selected[1]}"} if selected else {}
        response = storage.client.get_object(Bucket=storage.bucket, Key=asset["object_key"], **args)
    except Exception:
        raise HTTPException(503, "Медиа временно недоступно") from None
    body = response["Body"]
    if selected:
        first, last = selected
        headers.update(
            {
                "Content-Length": str(last - first + 1),
                "Content-Range": f"bytes {first}-{last}/{size}",
            }
        )

    def stream():
        try:
            while chunk := body.read(256 * 1024):
                yield chunk
        finally:
            body.close()

    return MediaResponse(
        stream(),
        status_code=206 if selected else 200,
        headers=headers,
        s3_body=body,
    )

export function WatchPage() {
  const { id } = useParams();
  const { session } = useAuth();
  const [video, setVideo] = useState<Video | null>(null);
  const [error, setError] = useState("");
  const [recommendations, setRecommendations] = useState<VideoCardData[]>([]),
    [recError, setRecError] = useState(""),
    [recLoading, setRecLoading] = useState(true),
    [recRevision, setRecRevision] = useState(0);
  const [theater, setTheater] = useState(false);
  const [mobilePlayer, setMobilePlayer] = useState(
    () => window.matchMedia("(max-width: 600px)").matches,
  );
  useEffect(() => {
    const query = window.matchMedia("(max-width: 600px)");
    const changed = () => {
      setMobilePlayer(query.matches);
      if (query.matches) setTheater(false);
    };
    changed();
    query.addEventListener("change", changed);
    return () => query.removeEventListener("change", changed);
  }, []);
  useEffect(() => {
    const controller = new AbortController();
    setVideo(null);
    setError("");
    let unavailable = false, checking = false;
    const markUnavailable = () => {
      unavailable = true;
      setVideo(null);
      setError("Видео не найдено или недоступно");
    };
    const check = async (initial = false) => {
      if (checking || unavailable || controller.signal.aborted) return;
      checking = true;
      try {
        const value = await api(`/videos/${id}`, { signal: controller.signal });
        if (!controller.signal.aborted && !unavailable) setVideo(previous =>
          previous && previous.id === value.id
            ? { ...value, views_count: Math.max(previous.views_count, value.views_count) }
            : value);
      } catch (failure) {
        if (!controller.signal.aborted) {
          if (failure instanceof HttpError && failure.status === 404) markUnavailable();
          else if (initial) setError((failure as Error).message);
        }
      } finally { checking = false; }
    };
    const deleted = (event: Event) => {
      if ((event as CustomEvent<string>).detail === id) markUnavailable();
    };
    const storageChanged = (event: StorageEvent) => {
      if (event.key !== "video-service:deleted" || !event.newValue) return;
      try { if (JSON.parse(event.newValue).id === id) markUnavailable(); }
      catch { /* Ignore unrelated malformed local data. */ }
    };
    const focused = () => void check();
    void check(true);
    const timer = setInterval(() => void check(), 5000);
    window.addEventListener("video-deleted", deleted);
    window.addEventListener("storage", storageChanged);
    window.addEventListener("focus", focused);
    return () => {
      controller.abort();
      clearInterval(timer);
      window.removeEventListener("video-deleted", deleted);
      window.removeEventListener("storage", storageChanged);
      window.removeEventListener("focus", focused);
    };
  }, [id, session]);
  useEffect(() => {
    const controller = new AbortController();
    setRecommendations([]);
    setRecError("");
    setRecLoading(true);
    api("/videos?limit=16", { signal: controller.signal })
      .then((page: Page<VideoCardData>) => {
        if (!controller.signal.aborted)
          setRecommendations(page.items.filter((item) => item.id !== id));
      })
      .catch(() => {
        if (!controller.signal.aborted)
          setRecError("Не удалось загрузить рекомендации. Попробуйте ещё раз.");
      })
      .finally(() => {
        if (!controller.signal.aborted) setRecLoading(false);
      });
    return () => controller.abort();
  }, [id, session, recRevision]);
  if (error)
    return (
      <div className="empty-state" role="alert">
        <h1>Видео недоступно</h1>
        <p>{error}</p>
        <Link className="button-link" to="/">
          На главную
        </Link>
      </div>
    );
  if (!video)
    return (
      <div className="watch-loading" role="status">
        <div className="skeleton skeleton-thumb" />
        Загрузка видео…
      </div>
    );
  return (
    <section className={`watch-page${theater ? " theater-mode" : ""}`}>
      <div className="watch-player">
        <VideoPlayer
          key={id}
          id={id!}
          title={video.title}
          theater={theater}
          mobile={mobilePlayer}
          onTheater={() => setTheater((value) => !value)}
          onViewCount={(count) => setVideo(previous => previous && previous.id === id
            ? { ...previous, views_count: Math.max(previous.views_count, count) } : previous)}
        />
      </div>
      <div className="watch-main">
        <h1>{video.title}</h1>
        <p className="watch-views" aria-live="polite">{formatViews(video.views_count)}</p>
        <div className="watch-author-row">
          <WatchChannel
            key={`${video.id}:${session?.user.id || "guest"}`}
            username={video.author}
          />
          <div id="watch-actions" className="watch-actions" />
        </div>
        <details className="description-panel">
          <summary>
            <span>
              {video.description
                ? video.description.split("\n")[0]
                : "Описание не добавлено"}
            </span>
            <b>Ещё</b>
          </summary>
          <p className="video-description">{video.description}</p>
        </details>
        {session?.user.username === video.author && (
          <Link className="studio-watch-link" to="/studio">
            Управлять видео в Studio
          </Link>
        )}
        <VideoInteractions
          key={`${video.id}:${session?.user.id || "guest"}`}
          id={video.id}
          initial={{
            likes_count: video.likes_count || 0,
            liked_by_me: !!video.liked_by_me,
          }}
          onUnavailable={() => {
            setVideo(null);
            setError("Видео не найдено или недоступно");
          }}
        />
      </div>
      <aside className="watch-recommendations" aria-label="Рекомендации" aria-busy={recLoading}>
        <h2>Ещё видео</h2>
        {recLoading && <p role="status">Загрузка рекомендаций…</p>}
        {recommendations.map((item) => (
          <VideoCard key={item.id} compact video={item} />
        ))}
        {recError && (
          <p role="alert">
            setMuted(!!video.current?.muted);
          }}
          onRateChange={() => setSpeed(video.current?.playbackRate || 1)}
          onError={() => {
            setBuffering(false);
            setError(
              "Не удалось воспроизвести видео. Возможно, доступ изменился; обновите страницу.",
            );
          }}
        />
        {!playing && !error && !buffering && (
          <button
            className="player-center"
            aria-label={
              started ? "Продолжить воспроизведение" : "Воспроизвести видео"
            }
            onClick={() => void toggle()}
          >
            <Icon name="play" size={36} />
          </button>
        )}
        {buffering && !error && (
          <span
            className="player-spinner"
            role="status"
            aria-label="Буферизация"
          />
        )}
        {error && (
          <div className="player-error" role="alert">
            {error}
            <button
              onClick={() => {
                setError("");
                video.current?.load();
              }}
            >
              Повторить воспроизведение
            </button>
          </div>
        )}
      </div>
      <div
        className="player-controls"
        inert={!(mobile || visible || !playing || settings)}
      >
        <input
          className="seek-bar"
          type="range"
          aria-label="Позиция воспроизведения"
          min={0}
          max={duration || 1}
          step={0.1}
          value={Math.min(time, duration || 1)}
          disabled={!duration}
          onChange={(e) => seek(Number(e.target.value))}
          aria-valuetext={`${formatDuration(time * 1000)} из ${formatDuration(duration * 1000)}`}
          style={
            {
              "--progress": `${duration ? (time / duration) * 100 : 0}%`,
            } as CSSProperties
          }
        />
        <div className="player-control-row">
          <button
            className="player-button"
            aria-label={playing ? "Пауза" : "Воспроизвести"}
            title={playing ? "Пауза (K)" : "Воспроизвести (K)"}
            onClick={() => void toggle()}
          >
            <Icon name={playing ? "pause" : "play"} />
          </button>
          {!mobile && (
            <>
              <button
                className="player-button"
                aria-label={
                  muted || volume === 0 ? "Включить звук" : "Выключить звук"
                }
                title="Звук (M)"
                onClick={() => {
                  if (video.current) {
                    if (volume === 0) changeVolume(1);
                    else video.current.muted = !video.current.muted;
                  }
                }}
              >
                <Icon name={muted || volume === 0 ? "mute" : "volume"} />
              </button>
              <input
                className="volume-bar"
                aria-label="Громкость"
                type="range"
                min={0}
                max={1}
                step={0.05}
                value={muted ? 0 : volume}
                onChange={(e) => changeVolume(Number(e.target.value))}
              />
            </>
          )}
